-- Siatkówka plażowa, BMX wyścigi, boks i wspinaczka sportowa – tablice kwot LA28 i kalendarze.
-- Siatkówka dostaje poddyscypliny (halowa, plażowa). Można uruchomić ponownie.
-- Źródła: systemy kwalifikacji FIVB, UCI, World Boxing i World Climbing dla LA28.

insert into public.dyscypliny (slug, nazwa, nadrzedna_id, kolejnosc)
select v.slug, v.nazwa, s.id, v.kol
from (values ('siatkowka-halowa', 'Siatkówka halowa', 1), ('siatkowka-plazowa', 'Siatkówka plażowa', 2)) as v(slug, nazwa, kol)
cross join (select id from public.dyscypliny where slug = 'siatkowka') s
on conflict (slug) do update set nadrzedna_id = excluded.nadrzedna_id, nazwa = excluded.nazwa;

update public.dyscypliny set opis_kafla = v.opis from (values
  ('siatkowka', 'Siatkówka halowa i plażowa'),
  ('siatkowka-plazowa', 'Kobiety i mężczyźni · 24 pary · ranking FIVB'),
  ('bmx-wyscigi', 'Kobiety i mężczyźni · ranking UCI krajów'),
  ('boks', '7 kategorii kobiet i 7 mężczyzn · turnieje kwalifikacyjne'),
  ('wspinaczka-sportowa', 'Boulder, prowadzenie i na czas – osobno')
) as v(slug, opis) where dyscypliny.slug = v.slug;

insert into public.konkurencje (dyscyplina_id, slug, nazwa, plec, miejsc, data_startu, opis, algorytm)
