from (values
  ('siatkowka-plazowa', 'kobiety', 'Siatkówka plażowa – kobiety', 'K', 24::smallint, null, '24 pary. Maks. 2 pary z kraju.', '{"typ": "kwoty", "etykieta": "Kobiety"}'),
