  ('boks', 'mezczyzni', 'Boks – mężczyźni', 'M', 124::smallint, null, '7 kategorii wagowych, 124 miejsca; maks. 1 zawodnik z kraju w kategorii.', '{"typ": "kwoty", "etykieta": "Mężczyźni"}'),
  ('wspinaczka-sportowa', 'boulder-kobiety', 'Wspinaczka – boulder, kobiety', 'K', 12::smallint, null, '12 zawodników. Maks. 2 z kraju.', '{"typ": "kwoty", "etykieta": "Boulder – kobiety"}'),
  ('wspinaczka-sportowa', 'boulder-mezczyzni', 'Wspinaczka – boulder, mężczyźni', 'M', 12::smallint, null, '12 zawodników. Maks. 2 z kraju.', '{"typ": "kwoty", "etykieta": "Boulder – mężczyźni"}'),
  ('wspinaczka-sportowa', 'prowadzenie-kobiety', 'Wspinaczka – prowadzenie, kobiety', 'K', 12::smallint, null, '12 zawodników. Maks. 2 z kraju.', '{"typ": "kwoty", "etykieta": "Prowadzenie – kobiety"}'),
